from common import *
S=[
section('7.1','Lines, angles and angle facts','Angle facts',
 'Name the relationship first: straight line, full turn, vertically opposite or right angle.',
 ['Angles on a straight line add to 180°; angles around a point add to 360°. Vertically opposite angles are equal. A right angle is 90°.',
  'Classify angles as acute (<90°), right (90°), obtuse (between 90° and 180°) or reflex (between 180° and 360°). A diagram is not always drawn to scale, so use stated facts rather than appearance.'],
 ex('Find a missing angle','Two lines cross. One angle is 115°.', ['The vertically opposite angle is 115°.','Each adjacent angle is 180°−115° = 65°.'], '115°, 65°, 115°, 65° around the intersection.'),
 'Do not assume lines are parallel or angles equal unless marked or stated. “Looks like 90°” is not a reason.',[
 q('7.1.1','fluency','An angle on a straight line is 65°. Find its neighbour.','115°.','180−65.',v('180-65',115)),
 q('7.1.2','fluency','Two lines cross and one angle is 115°. Find the other three.','65°, 115°, 65°.','Vertically opposite angles are equal; adjacent angles sum to 180°.',v('[180-115,115,180-115]',[65,115,65])),
 q('7.1.3','reasoning','Three angles around a point are 90°, 110° and 75°. Find the fourth.','85°.','360−(90+110+75).',v('360-(90+110+75)',85)),
 q('7.1.4','fluency','Classify 35°, 90°, 125° and 210°.','Acute, right, obtuse, reflex.','Compare with 90°, 180° and 360°.',v('[classify_angle(a) for a in [35,90,125,210]]',['acute','right','obtuse','reflex'])),
 q('7.1.5','application','A ramp makes 12° with the ground. What angle does it make with the vertical?','78°.','Ground and vertical are perpendicular: 90−12.',v('90-12',78)),
 q('7.1.6','challenge','Can two adjacent angles on a straight line both be obtuse? Explain.','No. Their sum would exceed 180°.','Each obtuse angle is greater than 90°.',v('91+91>180',True))],{'kind':'crossing_lines','angle':115,'caption':'Vertically opposite angles are equal; adjacent angles on a straight line sum to 180°.'}),
section('7.2','Parallel lines and triangles','Parallel and triangle facts',
 'Use corresponding, alternate and co-interior angles only when the lines are parallel.',
 ['When a transversal crosses parallel lines, corresponding angles are equal, alternate angles are equal, and co-interior angles add to 180°.',
  'Triangle angles sum to 180°. An exterior angle equals the sum of the two opposite interior angles. In an isosceles triangle, the angles opposite the equal sides are equal.'],
 ex('A roof truss','The two base angles are 65° each.', ['Apex = 180−65−65 = 50°.','The exterior angle at a base is 180−65 = 115°.'], 'Apex 50°; exterior base angle 115°.'),
 'The triangle sum is 180°, not 360°. Parallel-line facts need the parallel condition.',[
 q('7.2.1','fluency','A triangle has angles 65° and 65°. Find the third.','50°.','180−130.',v('180-65-65',50)),
 q('7.2.2','fluency','Parallel lines are cut by a transversal. One angle is 65°. Find its corresponding, alternate and co-interior angles.','65°, 65°, 115°.','Corresponding and alternate are equal; co-interior sums to 180°.',v('[65,65,180-65]',[65,65,115])),
 q('7.2.3','reasoning','An exterior angle of a triangle is 115° and one opposite interior angle is 65°. Find the other.','50°.','115−65.',v('115-65',50)),
 q('7.2.4','application','An isosceles triangle has apex 50°. Find each base angle.','65°.','(180−50)÷2.',v('(180-50)//2',65)),
 q('7.2.5','reasoning','Can a triangle have angles 60°, 70° and 60°? Explain.','No. They sum to 190°, not 180°.','The angle sum is a necessary condition.',v('60+70+60',190)),
 q('7.2.6','challenge','A triangle has angles in the ratio 2:3:4. Find them.','40°, 60°, 80°.','Nine parts make 180°, so one part is 20°.',v('[180*k//9 for k in [2,3,4]]',[40,60,80]))],{'kind':'parallel_lines','angle':65,'caption':'With parallel lines: corresponding and alternate angles are 65°; the co-interior angle is 115°.'}),
section('7.3','Polygons and the triangle inequality','Polygons and possible triangles',
 'Split polygons into triangles; test whether three lengths can close a triangle.',
 ['An n-sided polygon can be split into n−2 triangles from one vertex, so its interior angle sum is (n−2)×180°. The exterior angles of any convex polygon sum to 360°.',
  'For a regular n-gon, each exterior angle is 360°/n and each interior angle is 180°−360°/n. Three lengths form a non-degenerate triangle exactly when the sum of the two shorter lengths exceeds the longest.'],
 ex('A pentagon and a possible triangle','Find the interior sum of a pentagon; test sides 3, 4, 8.', ['Pentagon: (5−2)×180 = 540°.','3+4 = 7 < 8, so no triangle.'], '540°; no triangle.'),
 'Equality gives a straight line, not a triangle. The inequality must be strict.',[
 q('7.3.1','fluency','Find the interior angle sums of a quadrilateral, pentagon and hexagon.','360°, 540°, 720°.','Use (n−2)×180°.',v('[(n-2)*180 for n in [4,5,6]]',[360,540,720])),
 q('7.3.2','fluency','Find each interior and exterior angle of a regular hexagon.','Interior 120°; exterior 60°.','360÷6 = 60; 180−60.',v('[180-360/6,360/6]',[120,60])),
 q('7.3.3','reasoning','Can sides 3 cm, 4 cm and 8 cm form a triangle? What about 4, 5, 9?','Neither. 3+4<8; 4+5=9 gives a degenerate straight line.','The two shorter sides must sum to more than the longest.',v('[3+4>8,4+5>9]',[False,False])),
 q('7.3.4','application','A regular polygon has exterior angle 45°. How many sides?','8.','360÷45.',v('360//45',8)),
 q('7.3.5','reasoning','Why is checking only the two shorter sides against the longest enough?','If a+b>c with c longest, then a+c>b and b+c>a automatically because c is at least as large as the other sides.','The other two inequalities follow from ordering.',v('sorted([6,7,10])[0]+sorted([6,7,10])[1]>sorted([6,7,10])[2]',True)),
 q('7.3.6','challenge','Two sides are 5 cm and 8 cm. List all whole-number third sides.','4, 5, 6, 7, 8, 9, 10, 11, 12 cm.','Need 3 < x < 13.',v('[x for x in range(1,20) if 5+8>x and 5+x>8 and 8+x>5]',list(range(4,13))))],{'kind':'polygon','n':6,'caption':'A hexagon splits into four triangles: interior sum 4 × 180° = 720°.'}),
section('7.4','Ruler-and-compass constructions','Construct',
 'Use equal radii to force a property, keep construction arcs visible and check the defining relationship.',
 ['A perpendicular bisector cuts a segment at its midpoint at 90°. Draw equal-radius arcs from both endpoints, with radius greater than half the segment, then join the arc intersections.',
  'An angle bisector uses an arc from the vertex, then equal arcs from the two arm intersections. For an SSS triangle, draw one side and use the other two lengths as arc radii from its endpoints.'],
 ex('Construct a 5–6–7 triangle','Use the longest side as the base.', ['Draw AB = 7 cm.','From A draw radius 5 cm; from B draw radius 6 cm. Let the arcs meet at C.','Join AC and BC; check 5+6>7.'], 'Triangle ABC has sides 5, 6 and 7 cm.'),
 'Do not change the compass radius between the paired arcs of a bisector. A protractor drawing is a measurement, not a ruler-and-compass construction.',[
 q('7.4.1','fluency','For a 6 cm segment, what must be true of the compass radius used for a perpendicular bisector?','Greater than 3 cm.','The arcs must meet above and below the segment.',v('6/2',3,contains=['Greater than 3'])),
 q('7.4.2','reasoning','A 70° angle is bisected by construction. What should each half measure?','35°.','A bisector makes two equal angles.',v('70/2',35)),
 q('7.4.3','application','Can a 5 cm, 6 cm, 7 cm triangle be constructed? State the check.','Yes: 5+6>7.','The two shorter sides exceed the longest.',v('5+6>7',True)),
 q('7.4.4','reasoning','Why must construction arcs be left visible?','They record the equal-radius method and allow the construction to be checked.','The arcs are evidence, not clutter.',v('5+6>7',True,contains=['evidence'])),
 q('7.4.5','application','Describe how to locate the midpoint of a 6 m base in a 1:20 scale drawing.','Draw a 30 cm base and construct its perpendicular bisector; it meets the base at 15 cm.','6 m ÷ 20 = 0.3 m = 30 cm; half is 15 cm.',v('[600/20,600/20/2]',[30,15])),
 q('7.4.6','challenge','A student uses radius 2 cm from both ends of a 6 cm segment. Explain why the perpendicular-bisector construction fails.','The arcs do not meet: 2+2<6. The radius must exceed 3 cm.','Equal radii are not enough; they must be long enough to intersect.',v('2+2<6',True))],{'kind':'compass_bisector','length':6,'radius':4,'caption':'Equal radii from A and B locate P and Q. Line PQ is the perpendicular bisector of AB.'})
]
